text:
{
  "findings": [
    {
      "ref": "[R98]",
      "area": "contact",
      "claim": "A parent reports that imported skins revert to Steve or Alex and are not visible to friends.",
      "stance": "risk",
      "quote": "I noticed all my skins are Steve. I always import skins and whenever I close the app they turn back into Steve! Even all the other default skins look like Steve."
    },
    {
      "ref": "[R106]",
      "area": "money",
      "claim": "A parent reports that the game encourages spending on add-ons and mentions high prices for Minecoins.",
      "stance": "risk",
      "quote": "I think it’s pretty scummy to not state up front that this is a monthly charge, not a one-and-done payment."
    },
    {
      "ref": "[R123]",
      "area": "money",
      "claim": "A parent reports that purchased add-ons do not refund Minecoins when deleted.",
      "stance": "risk",
      "quote": "I bought this morph add-on. I really don’t like it so I deleted it and it didn’t give me my mine coins back."
    },
    {
      "ref": "[R126]",
      "area": "money",
      "claim": "A parent reports being charged multiple times for the same add-on without receiving the product.",
      "stance": "risk",
      "quote": "Attempted to buy add ons like I have in the past, it wasn’t working and after the third attempt for the same product, I was charged for buying the same add on 3 times."
    },
    {
      "ref": "[R144]",
      "area": "age_gating",
      "claim": "A parent reports that parental controls cannot be turned off despite attempts.",
      "stance": "risk",
      "quote": "When my parents try to turn off parental controls it won't work. We tried everything but it refused to change."
    },
    {
      "ref": "[R155]",
      "area": "data",
      "claim": "A parent reports that the game is unavailable in China and wishes for its return.",
      "stance": "neutral",
      "quote": "please return to China"
    },
    {
      "ref": "[R157]",
      "area": "skin",
      "claim": "A player reports that their custom skin is reset to default skins after loading.",
      "stance": "risk",
      "quote": "YOU RESET MY BEUTIFULL SKIN INTO STINKY DEFAULT SKINS!!!!"
    },
    {
      "ref": "[R159]",
      "area": "data",
      "claim": "A player reports that collected items like coal disappear from inventory after leaving the game.",
      "stance": "risk",
      "quote": "My COAL DISAPPEARS! When I come to play again after a few hours, I notice that all my coal disappears from my items."
    },
    {
      "ref": "[R160]",
      "area": "money",
      "claim": "A player mentions that the game has no ads but implies that the cost of Minecoins is a concern.",
      "stance": "neutral",
      "quote": "This is the best app ever made. I say Minecraft is better than TickTock by a lot."
    },
    {
      "ref": "[R162]",
      "area": "data",
      "claim": "A parent reports that the Chinese version of Minecraft is priced lower and offers more mod support than the international version.",
      "stance": "neutral",
      "quote": "比网易的优质几倍 几乎没有需要内购的内容 很多mod可以直接导入使用 版本上领先刚毅的 $6.99的价格买一个这个很划算！！！"
    },
    {
      "ref": "[R16]",
      "area": "contact",
      "claim": "A parent reports that the game requires a Microsoft account for all features, including free mods, and that the verification process fails.",
      "stance": "risk",
      "quote": "So stupid you need a Microsoft account for everything you can’t even download free mods the only way you can do that is by going on an app that basically cost money and even if you did somehow get that for free, it doesn’t even work it. Verity doesn’t even talk."
    },
    {
      "ref": "[R111]",
      "area": "money",
      "claim": "A parent reports being charged twice for a purchased item that was never delivered.",
      "stance": "risk",
      "quote": "I paid two times for \"Villager news\" and wasted $14 and I still haven't got it so I just wasted money on something that I didn't even get"
    }
  ]
}
